package com.adalat.service.ai;  import com.adalat.dto.ai.AiIntakeRequestDTO; import com.adalat.dto.ai.AiIntakeResponseDTO; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.BeforeEach; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.web.reactive.function.client.WebClient; import reactor.core.publisher.Mono;  import java.util.concurrent.TimeoutException; import java.net.UnknownHostException;  import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.ArgumentMatchers.anyString; import static org.mockito.Mockito.*;  @ExtendWith(MockitoExtension.class) public class ExternalLlmLegalAiProviderTest {      private ExternalLlmLegalAiProvider provider;     private AiProperties properties;      @Mock     private WebClient.Builder webClientBuilder;     @Mock     private WebClient webClient;     @Mock     private WebClient.RequestBodyUriSpec requestBodyUriSpec;     @Mock     private WebClient.RequestBodySpec requestBodySpec;     @Mock     private WebClient.ResponseSpec responseSpec;      @BeforeEach     void setUp() {         properties = new AiProperties();         properties.setApiKey("test-key");         properties.setModel("gemini-3.5-flash");         properties.setBaseUrl("http://localhost");         properties.setTimeoutSeconds(30);          when(webClientBuilder.baseUrl(anyString())).thenReturn(webClientBuilder);         when(webClientBuilder.defaultHeader(anyString(), anyString())).thenReturn(webClientBuilder);         when(webClientBuilder.build()).thenReturn(webClient);          provider = new ExternalLlmLegalAiProvider(webClientBuilder, properties, new ObjectMapper());     }      @SuppressWarnings("unchecked")     private void mockWebClientResponse(Mono<String> responseMono) {         when(webClient.post()).thenReturn(requestBodyUriSpec);         when(requestBodyUriSpec.uri(anyString())).thenReturn(requestBodySpec);                  WebClient.RequestHeadersSpec<?> headersSpec = (WebClient.RequestHeadersSpec<?>) requestBodySpec;         when(requestBodySpec.bodyValue(any())).thenReturn((WebClient.RequestHeadersSpec) headersSpec);                  when(requestBodySpec.retrieve()).thenReturn(responseSpec);         when(responseSpec.bodyToMono(String.class)).thenReturn(responseMono);     }      @Test     void testGeminiDirectly_ValidResponse() {         String json = "{\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"{\\\"assistantMessage\\\":\\\"hello\\\"}\"}]}}]}";         mockWebClientResponse(Mono.just(json));          AiIntakeRequestDTO request = new AiIntakeRequestDTO();         AiIntakeResponseDTO response = provider.processMessage(request);                  assertNotNull(response);         assertEquals("hello", response.getAssistantMessage());     }          @Test     void testGeminiDirectly_UnknownField() {         String json = "{\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"{\\\"assistantMessage\\\":\\\"hello\\\",\\\"thoughtProcess\\\":\\\"thinking\\\"}\"}]}}]}";         mockWebClientResponse(Mono.just(json));          AiIntakeRequestDTO request = new AiIntakeRequestDTO();         AiIntakeResponseDTO response = provider.processMessage(request);                  assertNotNull(response);         assertEquals("hello", response.getAssistantMessage());     }      @Test     void testTimeoutError() {         mockWebClientResponse(Mono.error(new TimeoutException("Timeout")));                  AiIntakeRequestDTO request = new AiIntakeRequestDTO();         AiProviderException ex = assertThrows(AiProviderException.class, () -> provider.processMessage(request));         assertEquals(AiProviderException.ErrorCategory.TIMEOUT, ex.getCategory());     }          @Test     void testUnknownHostException() {         mockWebClientResponse(Mono.error(new UnknownHostException("Unknown host")));                  AiIntakeRequestDTO request = new AiIntakeRequestDTO();         AiProviderException ex = assertThrows(AiProviderException.class, () -> provider.processMessage(request));         assertEquals(AiProviderException.ErrorCategory.NETWORK_ERROR, ex.getCategory());     }          @Test     void testEmptyCandidates() {         String json = "{\"candidates\":[]}";         mockWebClientResponse(Mono.just(json));                  AiIntakeRequestDTO request = new AiIntakeRequestDTO();         AiProviderException ex = assertThrows(AiProviderException.class, () -> provider.processMessage(request));         assertEquals(AiProviderException.ErrorCategory.INVALID_PROVIDER_RESPONSE, ex.getCategory());     } }